import * as THREE from "three";
import { RoundedBoxGeometry } from "three/examples/jsm/geometries/RoundedBoxGeometry.js";

export type UtilityTowModelOptions = {
  castShadow?: boolean;
  receiveShadow?: boolean;
  paintColor?: THREE.ColorRepresentation;
  boomAngleDeg?: number;
  boomExtension?: number; // 0 to 1
  outriggersDeployed?: boolean;
};

/**
 * Derived binding — assets/workbench/utility-tow-recovery-01/rig-envelope.json
 * Generated by `tools/derive-rig-asset-envelope.ts heavy-utility-tow-recovery-01`
 * from RIG_PROFILES via rigBlockout(). The reference plates supply FORM;
 * these numbers supply DIMENSIONS. Do not hand-edit them away from the
 * envelope: re-run the derive tool and keep the drift-guard test green.
 */
export const UTILITY_TOW_ENVELOPE = {
  track: 3.0,
  wheelbase: 4.2,
  frontTyreRadius: 0.765,
  rearTyreRadius: 0.935,
  hull: { width: 3.15, height: 0.77, depth: 5.88, centerY: 1.1 },
  root: { width: 3.935, depth: 6.07, halfDepth: 3.035 },
} as const;

// The third (middle) axle is visual 6x6 identity only — the kernel simulates
// exactly four contacts (WHEEL_LOCAL_SIGNS), so the simulated pair MUST be the
// front axle (z = +wheelbase/2) and the rearmost axle (z = -wheelbase/2).
const MID_AXLE_Z = -0.85;

function fabricatedBoxGeometry(
  width: number,
  height: number,
  depth: number,
): RoundedBoxGeometry {
  const smallestDimension = Math.min(width, height, depth);
  return new RoundedBoxGeometry(
    width,
    height,
    depth,
    2,
    Math.min(0.028, smallestDimension * 0.12),
  );
}

const cabOrange = new THREE.MeshStandardMaterial({
  color: 0xda5a1b,
  metalness: 0.35,
  roughness: 0.45,
});

const frameDark = new THREE.MeshStandardMaterial({
  color: 0x222629,
  metalness: 0.8,
  roughness: 0.5,
});

const craneBone = new THREE.MeshStandardMaterial({
  color: 0xe0e4e8,
  metalness: 0.65,
  roughness: 0.35,
});

const hydraulicChrome = new THREE.MeshStandardMaterial({
  color: 0xd0d5dd,
  metalness: 0.95,
  roughness: 0.15,
});

const rubberBlack = new THREE.MeshStandardMaterial({
  color: 0x1a1c1e,
  metalness: 0.1,
  roughness: 0.85,
});

const glassMaterial = new THREE.MeshPhysicalMaterial({
  color: 0x88c4dc,
  metalness: 0.1,
  roughness: 0.1,
  transmission: 0.6,
  transparent: true,
  opacity: 0.7,
});

const beaconAmber = new THREE.MeshStandardMaterial({
  color: 0xffa500,
  emissive: 0xff7700,
  emissiveIntensity: 0.6,
  metalness: 0.2,
  roughness: 0.2,
});

const steelCable = new THREE.MeshStandardMaterial({
  color: 0x808588,
  metalness: 0.9,
  roughness: 0.3,
});

const hazardYellow = new THREE.MeshStandardMaterial({
  color: 0xf2c230,
  metalness: 0.3,
  roughness: 0.55,
});

const hazardBlack = new THREE.MeshStandardMaterial({
  color: 0x15181a,
  metalness: 0.3,
  roughness: 0.6,
});

const drawerSteel = new THREE.MeshStandardMaterial({
  color: 0x4a5054,
  metalness: 0.7,
  roughness: 0.45,
});

const fuelDrumRed = new THREE.MeshStandardMaterial({
  color: 0x8c2f24,
  metalness: 0.4,
  roughness: 0.5,
});

function finishMesh(
  mesh: THREE.Mesh,
  options: UtilityTowModelOptions,
): THREE.Mesh {
  mesh.castShadow = options.castShadow ?? true;
  mesh.receiveShadow = options.receiveShadow ?? true;
  return mesh;
}

/**
 * One mud wheel: faceted chunky tyre + stepped rim + hub, centred on its
 * axle so the group origin is the wheel centre (envelope localPosition).
 */
function buildWheel(
  radius: number,
  width: number,
  options: UtilityTowModelOptions,
): THREE.Group {
  const wheel = new THREE.Group();

  const tyre = finishMesh(
    new THREE.Mesh(
      new THREE.CylinderGeometry(radius, radius, width, 16),
      rubberBlack,
    ),
    options,
  );
  tyre.rotation.z = Math.PI / 2;
  wheel.add(tyre);

  const rim = finishMesh(
    new THREE.Mesh(
      new THREE.CylinderGeometry(radius * 0.55, radius * 0.55, width * 0.9, 12),
      frameDark,
    ),
    options,
  );
  rim.rotation.z = Math.PI / 2;
  wheel.add(rim);

  const hub = finishMesh(
    new THREE.Mesh(
      new THREE.CylinderGeometry(radius * 0.2, radius * 0.2, width * 0.95, 8),
      hydraulicChrome,
    ),
    options,
  );
  hub.rotation.z = Math.PI / 2;
  wheel.add(hub);

  return wheel;
}

export function createUtilityTowModel(
  options: UtilityTowModelOptions = {},
): THREE.Group {
  const root = new THREE.Group();
  root.name = "heavy-utility-tow-recovery-01";

  const paintMat = options.paintColor
    ? new THREE.MeshStandardMaterial({
        color: options.paintColor,
        metalness: 0.35,
        roughness: 0.45,
      })
    : cabOrange;

  const hull = UTILITY_TOW_ENVELOPE.hull;
  const deckTopY = hull.centerY + hull.height / 2; // 1.485 — hull top plane

  // 1. Chassis Frame — rails and deck authored inside the derived hull volume.
  const chassisGroup = new THREE.Group();
  chassisGroup.name = "chassis-frame";

  for (const side of [-1, 1]) {
    const rail = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.22, 0.34, 5.7), frameDark),
      options,
    );
    rail.position.set(side * 0.55, hull.centerY, 0);
    chassisGroup.add(rail);
  }

  const crossmember = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(1.32, 0.24, 0.3), frameDark),
    options,
  );
  crossmember.position.set(0, hull.centerY, 0.4);
  chassisGroup.add(crossmember);

  // Recovery deck between the wheel wells (tyre inner faces sit at ~±1.03 m
  // on the 3.0 m track), plus a full-width step plate behind the rear bogie.
  const deckPlate = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(2.1, 0.12, 5.6), frameDark),
    options,
  );
  deckPlate.position.set(0, deckTopY - 0.06, -0.1);
  chassisGroup.add(deckPlate);

  const rearStepPlate = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(3.0, 0.12, 0.4), frameDark),
    options,
  );
  rearStepPlate.position.set(0, deckTopY - 0.06, -2.82);
  chassisGroup.add(rearStepPlate);

  // Front push bumper with twin rated tow loops — inside root halfDepth.
  const pushBumper = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(2.9, 0.5, 0.28), frameDark),
    options,
  );
  pushBumper.position.set(0, 0.95, UTILITY_TOW_ENVELOPE.root.halfDepth - 0.16);
  chassisGroup.add(pushBumper);

  for (const side of [-1, 1]) {
    const towLoop = finishMesh(
      new THREE.Mesh(
        new THREE.TorusGeometry(0.16, 0.045, 10, 20),
        hydraulicChrome,
      ),
      options,
    );
    towLoop.position.set(side * 0.9, 0.95, pushBumper.position.z + 0.1);
    chassisGroup.add(towLoop);
  }

  root.add(chassisGroup);

  // 2. Operator Cabin — superstructure above the hull top, over the front axle.
  const cabGroup = new THREE.Group();
  cabGroup.name = "operator-cab";
  const cabBaseY = deckTopY;
  const cabHeight = 1.35;
  cabGroup.position.set(0, cabBaseY + cabHeight / 2, 1.45);

  const cabBody = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(2.6, cabHeight, 1.9), paintMat),
    options,
  );
  cabGroup.add(cabBody);

  const windshield = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(2.3, 0.7, 0.1), glassMaterial),
    options,
  );
  windshield.position.set(0, 0.22, 0.92);
  cabGroup.add(windshield);

  // Protective window grilles over the glass.
  for (const bar of [-0.75, -0.25, 0.25, 0.75]) {
    const grilleBar = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.06, 0.78, 0.06), frameDark),
      options,
    );
    grilleBar.position.set(bar, 0.22, 0.98);
    cabGroup.add(grilleBar);
  }

  // High-visibility side mirrors.
  for (const side of [-1, 1]) {
    const mirror = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.1, 0.3, 0.18), frameDark),
      options,
    );
    mirror.position.set(side * 1.42, 0.35, 0.75);
    cabGroup.add(mirror);
  }

  // Roof beacon bar.
  const beaconBar = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(1.2, 0.16, 0.26), beaconAmber),
    options,
  );
  beaconBar.position.set(0, cabHeight / 2 + 0.08, 0.1);
  cabGroup.add(beaconBar);

  root.add(cabGroup);

  // 3. Recovery Boom Assembly — 2-stage telescoping, raised rest pose keeps
  // the overhang inside the derived root depth.
  const boomGroup = new THREE.Group();
  boomGroup.name = "recovery-boom-assembly";
  boomGroup.position.set(0, deckTopY + 0.1, -1.0);

  const turntable = finishMesh(
    new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.75, 0.2, 24), frameDark),
    options,
  );
  boomGroup.add(turntable);

  const pivotBase = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(0.8, 0.6, 0.9), craneBone),
    options,
  );
  pivotBase.position.set(0, 0.4, 0);
  boomGroup.add(pivotBase);

  const boomAngle = (options.boomAngleDeg ?? 50) * (Math.PI / 180);
  const mainBoomArm = new THREE.Group();
  mainBoomArm.position.set(0, 0.6, 0.15);
  // The arm extends along local -Z; positive rotation about X raises it, so a
  // rearward boom lifts instead of dipping toward the rear axle.
  mainBoomArm.rotation.x = boomAngle;

  const baseBoomMesh = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(0.5, 0.5, 2.5), craneBone),
    options,
  );
  baseBoomMesh.position.set(0, 0, -1.1);
  mainBoomArm.add(baseBoomMesh);

  const extensionRatio = options.boomExtension ?? 0.3;
  const extBoomMesh = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(0.38, 0.38, 2.2), frameDark),
    options,
  );
  extBoomMesh.position.set(0, 0, -1.1 - extensionRatio * 1.4);
  mainBoomArm.add(extBoomMesh);

  const liftCylinder = finishMesh(
    new THREE.Mesh(
      new THREE.CylinderGeometry(0.08, 0.08, 1.4, 16),
      hydraulicChrome,
    ),
    options,
  );
  liftCylinder.position.set(0, 0.1, -0.6);
  liftCylinder.rotation.x = Math.PI / 6;
  boomGroup.add(liftCylinder);

  const hookGroup = new THREE.Group();
  hookGroup.position.set(0, 0, -2.35 - extensionRatio * 1.4);
  const hookBlock = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(0.3, 0.4, 0.25), craneBone),
    options,
  );
  hookGroup.add(hookBlock);

  const forgedHook = finishMesh(
    new THREE.Mesh(
      new THREE.TorusGeometry(0.12, 0.035, 12, 24, Math.PI * 1.5),
      frameDark,
    ),
    options,
  );
  forgedHook.position.set(0, -0.3, 0);
  forgedHook.rotation.z = Math.PI;
  hookGroup.add(forgedHook);

  mainBoomArm.add(hookGroup);
  boomGroup.add(mainBoomArm);
  root.add(boomGroup);

  // 4. Winch Spool Unit — 15T drum on the deck behind the cab.
  const winchGroup = new THREE.Group();
  winchGroup.name = "winch-spool-unit";
  winchGroup.position.set(0, deckTopY + 0.3, -0.25);

  const spoolDrum = finishMesh(
    new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.8, 20), steelCable),
    options,
  );
  spoolDrum.rotation.z = Math.PI / 2;
  winchGroup.add(spoolDrum);

  for (const side of [-1, 1]) {
    const flange = finishMesh(
      new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.06, 20), frameDark),
      options,
    );
    flange.rotation.z = Math.PI / 2;
    flange.position.x = side * 0.42;
    winchGroup.add(flange);
  }
  root.add(winchGroup);

  // 5. Outrigger Pads — stowed alongside the frame behind the rear bogie.
  const outriggerGroup = new THREE.Group();
  outriggerGroup.name = "outrigger-pads";
  outriggerGroup.position.set(0, 0.78, -2.55);

  const deployOffset = options.outriggersDeployed ? 0.6 : 0;
  for (const side of [-1, 1]) {
    const leg = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.8, 0.2, 0.35), frameDark),
      options,
    );
    leg.position.set(side * (1.1 + deployOffset), 0, 0);
    outriggerGroup.add(leg);

    const pad = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.4, 0.1, 0.4), hazardYellow),
      options,
    );
    pad.position.set(
      side * (1.5 + deployOffset),
      options.outriggersDeployed ? -0.68 : -0.15,
      0,
    );
    outriggerGroup.add(pad);

    const padLeg = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.12, 0.55, 0.12), frameDark),
      options,
    );
    padLeg.position.set(
      side * (1.5 + deployOffset),
      options.outriggersDeployed ? -0.33 : -0.08,
      0,
    );
    outriggerGroup.add(padLeg);
  }
  root.add(outriggerGroup);

  // 6. Rear hazard bumper — alternating yellow/black stripes.
  const rearBumper = new THREE.Group();
  rearBumper.name = "rear-hazard-bumper";
  rearBumper.position.set(0, 0.85, -(UTILITY_TOW_ENVELOPE.root.halfDepth - 0.14));
  const stripeWidth = 2.8 / 7;
  for (let index = 0; index < 7; index++) {
    const stripe = finishMesh(
      new THREE.Mesh(
        fabricatedBoxGeometry(stripeWidth, 0.34, 0.24),
        index % 2 === 0 ? hazardYellow : hazardBlack,
      ),
      options,
    );
    stripe.position.x = -2.8 / 2 + stripeWidth / 2 + index * stripeWidth;
    rearBumper.add(stripe);
  }
  root.add(rearBumper);

  // 7. Outboard Service Drawers + fuel drum & chain locker (socket inventory).
  const drawersGroup = new THREE.Group();
  drawersGroup.name = "service-drawers";
  const drawerUnit = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(0.38, 0.45, 1.4), drawerSteel),
    options,
  );
  drawerUnit.position.set(-0.84, hull.centerY, 0.65);
  drawersGroup.add(drawerUnit);
  for (const offset of [0.25, 0.65, 1.05]) {
    const drawerFace = finishMesh(
      new THREE.Mesh(fabricatedBoxGeometry(0.04, 0.1, 0.5), hazardYellow),
      options,
    );
    drawerFace.position.set(-1.04, hull.centerY + 0.08, offset - 0.3);
    drawersGroup.add(drawerFace);
  }
  root.add(drawersGroup);

  const lockerGroup = new THREE.Group();
  lockerGroup.name = "fuel-and-chain-locker";
  const fuelDrum = finishMesh(
    new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.19, 0.58, 14), fuelDrumRed),
    options,
  );
  fuelDrum.position.set(0.8, hull.centerY + 0.05, 0.25);
  lockerGroup.add(fuelDrum);
  const chainLocker = finishMesh(
    new THREE.Mesh(fabricatedBoxGeometry(0.4, 0.4, 0.6), drawerSteel),
    options,
  );
  chainLocker.position.set(0.8, hull.centerY, 1.0);
  lockerGroup.add(chainLocker);
  root.add(lockerGroup);

  // 8. Wheels — 6x6 identity; the four simulated contacts land exactly on the
  // envelope positions so the kernel-animated pair coincide with real tyres.
  const wheelsGroup = new THREE.Group();
  wheelsGroup.name = "6x6-wheels";

  const { track, wheelbase, frontTyreRadius, rearTyreRadius } =
    UTILITY_TOW_ENVELOPE;
  const halfTrack = track / 2;
  const halfWheelbase = wheelbase / 2;

  const wheelSpecs: {
    id: string;
    x: number;
    z: number;
    radius: number;
    simulationWheelIndex: number | null;
  }[] = [
    {
      id: "wheel-front-left",
      x: -halfTrack,
      z: halfWheelbase,
      radius: frontTyreRadius,
      simulationWheelIndex: 0,
    },
    {
      id: "wheel-front-right",
      x: halfTrack,
      z: halfWheelbase,
      radius: frontTyreRadius,
      simulationWheelIndex: 1,
    },
    {
      id: "wheel-mid-left",
      x: -halfTrack,
      z: MID_AXLE_Z,
      radius: rearTyreRadius,
      simulationWheelIndex: null,
    },
    {
      id: "wheel-mid-right",
      x: halfTrack,
      z: MID_AXLE_Z,
      radius: rearTyreRadius,
      simulationWheelIndex: null,
    },
    {
      id: "wheel-rear-left",
      x: -halfTrack,
      z: -halfWheelbase,
      radius: rearTyreRadius,
      simulationWheelIndex: 2,
    },
    {
      id: "wheel-rear-right",
      x: halfTrack,
      z: -halfWheelbase,
      radius: rearTyreRadius,
      simulationWheelIndex: 3,
    },
  ];

  for (const spec of wheelSpecs) {
    const wheel = buildWheel(spec.radius, spec.radius, options);
    wheel.name = spec.id;
    wheel.position.set(spec.x, spec.radius, spec.z);
    wheel.userData.simulationWheelIndex = spec.simulationWheelIndex;
    wheelsGroup.add(wheel);
  }
  root.add(wheelsGroup);

  // 9. Contact shadow decal — envelope ground-decal lift, presentation only.
  const groundDecal = new THREE.Mesh(
    new THREE.PlaneGeometry(3.6, 5.8),
    new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.22,
      depthWrite: false,
    }),
  );
  groundDecal.name = "ground-decal";
  groundDecal.rotation.x = -Math.PI / 2;
  groundDecal.position.y = 0.04;
  groundDecal.castShadow = false;
  groundDecal.receiveShadow = false;
  root.add(groundDecal);

  // 10. Front axis marker: a real brush guard at the nose. The rear marker is
  // the existing rear-hazard-bumper.
  const brushGuard = finishMesh(
    new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.22, 0.2), frameDark),
    options,
  );
  brushGuard.name = "front-marker";
  brushGuard.position.set(0, 0.7, halfWheelbase + 0.42);
  root.add(brushGuard);

  return root;
}

/**
 * Wheel spin pivots in kernel physics order: front-left, front-right,
 * rear-left, rear-right — the four wheels carrying
 * `userData.simulationWheelIndex`. The cosmetic middle axle of the 6x6 stays
 * out; it rolls with the visual deck, not the simulated contacts.
 */
export function utilityTowWheelPivots(model: THREE.Group): THREE.Group[] {
  const wheels: { index: number; group: THREE.Group }[] = [];
  model.traverse((object) => {
    const index = object.userData.simulationWheelIndex;
    if (typeof index === "number" && object instanceof THREE.Group) {
      wheels.push({ index, group: object });
    }
  });
  wheels.sort((a, b) => a.index - b.index);
  if (wheels.length !== 4 || wheels.some((w, i) => w.index !== i)) {
    throw new Error(
      "heavy-utility-tow-recovery-01: authored model is missing its simulated wheel pivots",
    );
  }
  return wheels.map((w) => w.group);
}
